window.WIKI.push(
 // ---------- 卷一 · 海洋纪 ----------
 {id:'hangmu',n:'航母',c:'琳的造物',r:'sea',e:[1],ll:[-3,41],s:'会游动的基地：琳把“远行者”改造成能放出部队主动猎杀的母舰。',
  d:'琳的“远行者”由上千万个细胞组成，它往下游到一片冰冷水域的白色细沙滩，发现那里的细胞多得是，却缝隙太窄进不去，又不想像从前那样造个基地守株待兔，于是把远行者改造了：身体继续胀大，仍是椭圆，体表的触须让它们自然死去，只留两条扁长的用来游动；皮层上开出一排由肌肉控制、大小不一的洞口，供部队进出。从前的基地只能黏在岩石上等食物经过，这个基地却能游动、主动出击，琳便给它取了新名“航母”。\n它在体内造出吞噬者：圆形，表面一张裂口大嘴，内壁布满锥刺并混着注酸者，配一颗眼球和两根扁触须；它们没有消化器官，力气耗尽时只要回到航母连上里面的脂肪触须就能补充。吞噬者从体表通道游出去猎杀细胞，把战利品吐回航母，琳一部分存成脂肪，一部分造更多的吞噬者，航母也越长越大。冰结在水中蔓延时，它关上所有洞口、缩回顶上的眼球、加速硬化皮层，把寒冰挡在了外面。它的身体由数亿细胞组成，前端两根长着眼球的触须，后面是喷水口；圆筒形的身躯适合撞击，琳在两侧造出巨锤般的触须，用来砸开冰层和叶形虫，还一锤把毒水母打飞到沙滩上。一只海星贴在它喷水口附近偷吃皮层，圆盾蠕虫改成的“守卫者”成了它的护卫；黑夜里琳在它头部挂上“灯笼”照路，暴流卷着十多亿细胞的它在黑暗中翻滚。水位下降时，它全身覆上白色壳质挡紫外线，又在体内造了气囊和储气者。\n陆上基地建起后，海床突然急速抬升，航母被冲到干地上，皮层被紫外线杀光，体内开始瓦解；琳在它体内一小块地方造出黑色壳质，把几个小细胞——观察者——包了进去。一亿多年后，贝希摩斯飞回故地，粉碎者在三米多深的沙下挖出了它：只有十几厘米长，形状像个弹头，细胞全死了却像木乃伊一样没有腐坏，里面的观察者仍处在似死非死的状态。',ch:'卷二《出发》《航母》《新养分系统》《离开冰层》《海中沙漠的生物们》《小而复杂》《黑夜下的沙漠》《登陆准备》《空气储藏和免疫系统》《震动》卷三《一亿年前的遗失物》《漫长的冬日》',rel:['lin','tunshizhe','huweizhe','yuandun','yexing','guanchazhe','origin','behemoth','fensuizhe']},
 {id:'tunshizhe',n:'吞噬者',c:'琳的造物',r:'sea',e:[1],ll:[-2,46],s:'琳最早的多细胞猎手之一：裂口大嘴的球形兵种，嘴里满是锥刺和溶解液。',
  d:'吞噬者诞生于航母时期，琳造它的目的就是“吞噬”。它是一个球体，长着裂口似的大嘴，嘴的内壁布满锥形细胞组成的尖刺，还夹着注酸者；靠近猎物时张开裂口，便能把它们吸进嘴里，用带溶解液的尖刺压碎。它有一颗眼球用来观察，靠两根扁长的触须游动。吞噬者不会消化——嘴里铺满锥刺和溶解液喷口，身体几乎全由肌肉细胞构成，省掉了吸收和输送养分的器官，好把速度和力量用到极致；快耗尽能量时，只要回到航母，接上航母里的脂肪触须就能充能。它们大小不一，最小的只有几百个细胞，最大的有成千上万个，以便钻进各种沙粒缝隙；有些皮层里混有闪光爆球，能自己发光，在沙粒下的黑暗里也看得清。正是看到吞噬者，琳意识到多细胞组合样样强于单个细胞，“器官”这个词也是这时冒出来的。\n吞噬者把猎到的食物吐回航母，琳把一部分做成脂肪储存，其余用来组合更多吞噬者，狩猎范围越扩越大。遇到圆盾蠕虫时，它们咬不动对方光滑的头和节肢硬壳，最大的吞噬者也不及对方钳子一半大；最后一只大型吞噬者咬住腕部关节，扯下一大块白色软组织，几十只随之钻进体内乱咬；从嘴部攻进食道的那批，则被嘴边的利刃大量切碎。此后琳增加了大型吞噬者，又特化出嘴里长满弯长尖硬“巨牙”的一种，专门对付多细胞生物。学会血管后，吞噬者也更新了：没有心脏，嘴的深处有一个连着血管的肌肉储藏囊，咬碎的食物进囊后，囊一收缩，就把食物和水挤进血管，由血管里的细胞分解、送往全身，多余的水循环回囊里，下次张嘴时排出。\n从此它们成了琳收集食物的主力：清扫冰壁上能钻进冰里的小细胞，撕咬叶形虫，钻进黑暗虫口中把它吃空，捕杀没加温的扁虫并守护饲养圈，把截贝体内的触须和免疫细胞撕成碎片；只有附在航母上的海星让它们咬不伤、也拉不下来。利维坦的“噬咬触须”同样只管咬碎不管消化；后来长成立体三角的基地，也照例放出吞噬者去收集食物。',ch:'卷二《航母》《埃迪卡拉纪蠕虫》《单细胞与多细胞》《内部》《新养分系统》《离开冰层》《海中沙漠的生物们》《小而复杂》《风暴前夕》《黑夜下的沙漠》《奇异的结晶与浅滩》《登陆准备》《落脚与远行》《深渊裂口》《绿化工程》',rel:['hangmu','yuandun','lin','yexing','jiebei','lvtan_beast','huweizhe','yunshuzhe']},
 {id:'yunshuzhe',n:'运输者',c:'琳的造物',r:'sea',e:[1,2],ll:[-8,39],s:'前圆后尖的流线型搬运兵种，最初运脂肪，后来变成会飞的鲨鱼形运载者。',
  d:'琳吃掉第二只叶形虫后，养分已经够复活圆盾蠕虫了，可它还想留下来多吃几只，于是组合出这种前圆后尖、可以叫作“流线型”的构造，在水里游得很快，取名“运输者”。第一批共十个，每个由十万以上的细胞组成，身体中段一圈扁长的小触须负责游动，空心的体内装满脂肪细胞，游回冰洞去复活圆盾蠕虫。\n第二次物种大灭绝来临前，琳回收了一部分绿毯，养分就存在一些身体椭圆、约两米长的运输者体内；为了不被吃掉，它们躲在入口很窄的洞里，灾难快到时才出来，跟着利维坦往北逃。海啸扑向北之大陆时，琳让它们全部加固外壳，可大部分仍被冲击挤扁；爬上满是鱼尸的岩地后，它们挤成一团一动不动，还是被迷雾里的蠕虫一只一只拖走咬碎，剩下的跟着利维坦钻进了尖柱林深处。\n后来的运输者大多是会飞的鲨鱼形。西航时，许多运输者漂在天空之舱周围，单独运载一些重要的生物，比如一群峡谷里最强盛的古鱿；还有几群挂着浮气囊，拖着三棵连根挖出的扭曲树。北边的地下基地被树根挤出地面时，一只五米多长的鲨鱼形运输者用肌肉带吊着梦境之脑飞了出去。大寒之前，它们在天上来回飞，把大陆上剩下的大型恐龙每种至少一雌一雄运上方舟；之后又驮着裹了绒球之毛的脑袋虫和爆哮虫，飞去看姆克图那座空空的岩山。大海啸期间，一只运输者在喷发的火山上空观察，闪开迎面飞来的火山弹。在地眼之湖，几只三米左右的鲨鱼形运输者潜到漆黑的湖底，放出小部队钻进沉船残骸的缝隙里打捞。',ch:'卷二《小而复杂》《极北之地》《攀岩》《迷雾中的暗杀者》卷三《新世界的白昼》《出航之前》卷四《弄死成活》卷五《起航》《严寒与希望》《计划》《打捞与野心》',rel:['yuandun','yexing','lvtan','lvtan_beast','mwrc','spires','tiankong','guyou','rqzj','fangzhou','dieye','landing']},
 {id:'huweizhe',n:'护卫者',c:'琳的造物',r:'sea',e:[1],ll:[-11,40],s:'琳用圆盾蠕虫空壳“复活”成的硬壳护卫，跟着航母作战。',
  d:'琳杀死圆盾蠕虫后，在它的空壳里填满肌肉、心脏和血管，做成了护卫者。它在沙地上爬得比原主还快，一身硬壳几乎不怕伤害。琳头一次拿它试手是对付一只毒水母，这才发现它的节肢没法往上弯，够不着漂在水里的水母；只好让航母先一锤把水母砸到沙滩上，护卫者再扑上去钳住触手、整个压住撕开。暴流过后它被冲得不知去向，埋进了沙里，好在有硬壳护着，里面的细胞都没事，琳点起“灯笼”在一个沙坑里把它找了回来。水位下降、紫外线逼近时，它的甲壳让它毫发无损，这让琳更想给自己也造出这样的硬壳；被困在扁虫用碎石粘成的巨石圈里时，也是它用节肢在巨石上挖出一个够航母钻出去的洞。\n琳给它的壳里装了气囊，它仍浮不起来，只能勉强“悬浮”；空心的尾巴内层铺上了爆球和注酸者，用来溶解、组合甲壳。一次它趴在航母后面，突然被一股远比自己大的力量拖进沙里——琳后悔没给它装眼睛，挖开沙子才看见它的后半身被两片圆盘形硬壳死死夹住，几乎要断成两截。那是藏在沙下的截贝，壳里无数尖头小触须正往它尾巴的薄弱处钻孔想吸细胞，可尾巴里的部队早已撤空。琳用吞噬者、注射者和爆炸锤打穿截贝，再让涂漆者修好它的裂伤。基地建起以后，航母多半浮在上方产兵，外出猎杀大型生物一般交给护卫者。',ch:'卷二《风暴前夕》《未来的光芒》《黑夜下的沙漠》《奇异的结晶与浅滩》《硬壳的进化》《登陆准备》《空气储藏和免疫系统》《落脚与远行》《基地》',rel:['yuandun','jiebei','hangmu','tunshizhe','lin']},
 {id:'dantou',n:'弹头',c:'琳的造物',r:'sea',e:[1],ll:[-26,35],s:'椭圆形、体内灌满海水的抗压探测兵种，被丢进海沟最深处，后来成了琳最爱用的探索兵。',
  d:'利维坦潜进深渊裂口时，越往下水压越大：漂着的小眼球和灯笼被挤得动弹不得甚至死掉，连利维坦的甲壳都裂了。琳算出了水压的道理和抗压的结构，不愿改利维坦，便造了这种新兵种：身体椭圆，外壳不算厚，里面灌满海水——要抵抗压力，就先用和四周一样的东西把自己填满。它完全不会游，利维坦一放出它，它就靠重力沉进海沟。落到底后，两侧外壳打开，伸出六条同样灌满水的节肢腿；头部开出两个洞口，露出一颗眼球和一盏灯笼，外面罩着透明薄壳，壳里也充着水，于是一点裂痕都没有。水占去了本该放肌肉和血管的地方，它走得很慢，好在只是探路。\n它在海沟底看见了凝固成灰色、却依然滚烫的熔岩，发着红光的裂缝，还有喜欢高温的单细胞；追着一团忽明忽灭的光时，它被身后的东西咬得粉碎。利维坦随即翻转身体打开出兵口，一次喷出上百只节肢末端带刃的战斗型弹头，找到了吃掉它的鲜红扁平的毯虫，爬上去割开伤口往里钻；毯虫发疯似的游出深渊，到了浅处便整个爆开。弹头到了低压的地方，会在壳上开几个小孔放水、吸进气泡浮上去，方便利维坦回收。\n此后它成了琳最爱用的探索兵种，分平常、陆地、深海三种：平常型靠喷水和两根扁平触手游动，体内有气囊能浮起。海床被抬出水面后，弹头们爬上这座“岛”，在壳上开孔吸氧，琳又造出专门去岛边吸水、替同伴补水的“补水弹头”，让它们给陆上的新基地涂壳筑墙；一只弹头被一块半球形的“石头”用钳子夹断，原来那是会放出小个体的“军团球”，弹头们掉头冲撞，把小军团球掀翻再刺穿。在冰洞外，它们又在搁浅的利维坦身下一遍遍挖隧道，让它的体重压塌地面，直到掉回水里。',ch:'卷二《深渊裂口》《熔岩与疯狂》《异变》《超个体》《冰河之间》',rel:['tanchong','abyss','lvtan_beast','hangmu']},
 {id:'lvzaoqiu',n:'绿藻球',c:'琳的造物',r:'sea',e:[1],ll:[64,36],s:'食光细胞的集合体，靠结晶发出的光也能制造养分。',
  d:'利维坦游到一块发光的结晶石上放出绿藻球，它们一靠近结晶，绿叶素就开始运转。琳由此决定在结晶上打孔、塞进光合细胞，把七个基地连成一个巨大的系统，还在利维坦体内弄了几个用灯笼照明的“自养室”，同时获得氧气和养分。',ch:'卷二《绿化工程》',rel:['qianjing','lvtan_beast']},
 {id:'qianjing',n:'千晶林地',c:'地理',r:'sea',e:[1],ll:[69,33],s:'锥形结晶一根根立在沙里的海底林地。',
  d:'这里的生物都和晶菌有关：外皮覆着菱形结晶小甲片的小生物，甲片缝里塞满晶菌；背着结晶硬壳的“螺”，壳里也有大量晶菌。琳第一次想到“共生”这个词。冰晶怪的壳也是这种不吸光、不吸热的特殊结晶，所以它们敢跳上陆地攻击利维坦。',ch:'卷二《结晶生态》',rel:['jingjun','bingjing']},
 {id:'zuankongyu',n:'钻孔鱼',c:'物种',r:'sea',e:[1],ll:[-15,49],s:'只有几毫米、成千上万一拥而上的小鱼。',
  d:'圆嘴扁鱼的进化型，没有变大，反而变得更小。圆形的嘴上长着弯钩般的尖牙，身上覆满倒刺般的小鳞片。它们撕开盔鱼的皮层，扭动着身体钻进伤口，直到吃掉每一个部分；琳在一旁围观的眼球也没被放过。',ch:'卷二《古生代爆发》',rel:[]},
 {id:'rouqiyu',n:'肉鳍鱼',c:'物种',r:'sea',e:[1,2],ll:[-17,53],s:'半米多长、身体两侧长着一对粗壮鳍肢的鱼。',
  d:'半米多长的鱼，身体两侧长着一对粗壮的鳍肢，所以叫肉鳍鱼。鲨鱼在海藻群里追逐它，它冲出海藻往水面逃，还是被一口撕下大片的肉，别的鲨鱼也闻声围过来分食。后来在北之大陆，印加虫群的水坑里养着肉鳍鱼；琳的飞行者循着腐臭找到登陆之地的岩地，满地都是肉鳍鱼、盔鱼、扁鱼甚至小鲨鱼的尸体，小光虫聚在上面啃食，最后只剩被啃光的骸骨。',ch:'卷二《怪兽的时代》卷三《坑中之洞》',rel:['landing','inca']},
 {id:'guangdao',n:'光导爆弹',c:'琳的造物',r:'sea',e:[1],ll:[-22,41],s:'带光球照明和眼球的追踪爆弹。',
  d:'和之前的爆弹一样靠喷水系统快速游动，周围加上了光球、前端装着眼球。琳在漆黑的深海里放出它们冲向一只节肢生物：扁椭圆的身体两侧长着叶状附肢，头部一对内弯的粗大节肢布满倒刺，琳叫它“钩虫”。光导爆弹的眼球让琳看见了钩虫的弱点——鳃。',ch:'卷二《黑夜中的光芒》',rel:['gouchong']},
 // ---------- 卷一 · 北之大陆纪 ----------
 {id:'lieshazhe',n:'猎杀者',c:'琳的造物',r:'north',e:[2],ll:[29.6,8.8],s:'琳登上北之大陆后造的第一支小型部队，身形如蝎、会变色。',
  d:'见识到周围物种进化之快后，琳认为单个探索已不安全，改成先派军队开路、再用绿毯占领，利维坦作为移动基地留在后方——十只猎杀者就是第一支部队。它们每只三十厘米长，身形如蝎，细长的腿配着刀锋般的前肢，从黑暗之原冲过河流，登上闪光林地。它们会变色，还特意撒满水晶尘，在发光苔藓上发出同样的光，与环境融为一体。和利维坦平时造的临时兵种不同，它们体内有完整的器官和循环系统，能就地进食，把养分存在腹部带回，凝成小球吐给利维坦。头一次狩猎，它们切破食苔甲的翅膀、刺进关节，三只负责吸血，其余切开硬甲，还分出两只赶走想来分一口的小爬行类。\n第一个猎杀者刚走出洞口，就被什么东西拖上高空咬碎了头；琳把它被吃剩一半的腹部溶解重组成一群“狂蜂”，反过来对付啃食残骸的银甲虫。此后部队里加进了尾部是炮口、发射溶甲爆弹的三十厘米炮击者；远征时猎杀者数量最多，排在两侧护卫载巢者，或背着狙击者、换成蕨类的颜色去偷袭鳞甲虫，再把被激怒的整群鳞甲虫引进丛林甩掉，回来嚼碎蕨类给新基地注入汁液，把狙击者安放到树上。后来它们还出现在山峰之湖的基地、家园树的防守战，以及深渊洞穴和瘟疫之首的调查中。',ch:'卷三《丛林猎手》《射炮步甲》《狙击手》《空地的埋伏》《地下世界的边境》《冲向战场》卷四《深渊的洞穴》《我来组成头部》',rel:['glow','lvtan','lvtan_beast','paojizhe','kuangfeng','shitaijia','shepao','linjia','jungle']},
 {id:'tucizhe',n:'突刺者',c:'琳的造物',r:'north',e:[2],ll:[15.8,-.2],s:'全身突然伸出尖刺、变成“刺猬”的圆盘兵种。',
  d:'用“隐形者”改装而成，直径三十厘米的圆盘身躯覆着甲壳、布满小孔。小节肢类趴上来啃咬时，藏在孔里的尖刺猛地突出，把它们全部刺穿。琳在尖柱林迎接第一个黑夜时准备了它们——不过后来冲出来的大型节肢类，一口下去，一个突刺者就碎了。',ch:'卷三《黑暗前夕》《尖柱林之谜》',rel:['spires']},
 {id:'paojizhe',n:'炮击者',c:'琳的造物',r:'north',e:[2],ll:[28.6,8.2],s:'尾巴是炮口、专射溶解爆弹的蝎形兵种，后来长到两米，是琳地面部队的炮兵主力。',
  d:'琳认为蝎子是它当时见过最完美的体型，攻守兼备又不影响速度，于是在扭曲丛林给猎杀者部队加进了三只炮击者：体长三十厘米，翘起的尾尖不是毒针而是炮口，专门发射穿甲用的溶甲爆弹，对付当时多为节肢类的猎物。进攻结晶虫穴时，炮击者已长到两米，整个身体就像一根粗长的炮管，除了最里面的一套维生系统，九成以上都用来制造和发射爆弹；它靠炸药冲击发射，三百米内百发百中，爆弹里装着溶解液和高温炸药，体侧八条节肢负责移动，背上常驮着狙击者。它们在洞穴里排成两排，把奇布查虫炸得四散。\n与阿兹特克虫隔河初战时，三十只炮击者是主攻力量，轻松扫清阿兹特克虫，随后却被五头深沙巴士撕得一只不剩；尖柱林歼灭战中，它与粉碎者一起装进空降仓砸进虫群。黑夜里一只巨蛛咬住一只炮击者往血管里注入高温液体，琳便让那只炮击者把全身转成溶解液、吸气膨胀后自爆。印加战争时，炮击者会临时改造体内结构，把单发炮管变成一次喷出许多弹丸的霰弹式，抬身迎击来袭的爆甲；对上裂地者时集体齐射，却也有大批被它铲起的巨石树木压死；粘蝎射出的粘球会堵住它的炮口，溶解液都化不开。穿过崩溃的地底时，一排新型炮击者向洞顶射出白色爆弹，炸开的丝线黏住裂缝，暂时撑住了崩塌。',ch:'卷三《丛林猎手》《朝深渊进攻》《结晶之中的战争》《奇布查的尽头》《初战》《护城河》《尖柱歼灭战》《黑夜》《首脑的疑惑》《冲突@99》《冲向战场》《轰炸烈焰》《在崩溃中前进》',rel:['lieshazhe','zhanxie','fensuizhe','jungle','chibcha','aztec','shenshabus','spires','inca','liedizhe','baojia']},
 {id:'fensuizhe',n:'粉碎者',c:'琳的造物',r:'north',e:[2,3],ll:[27.4,10.2],s:'碎岩者的升级型，三米长、带弹射锥角和尖啸声囊的冲锋兵种。',
  d:'它是碎岩者的升级型，体型和冲击力都更大，身长三米，头上的锥角能猛地弹出去。它还有一招：声囊特别发达，能发出极其尖锐的叫声，在结晶洞穴里久久回荡，把躲着的敌人逼出来。\n攻打结晶虫穴时，粉碎者打头阵撞开木材堆成的墙。奇布查虫成群飞来，十只粉碎者在狭窄的洞口排成一线，按琳事先分解奇布查虫、摸清其听觉结构后算出的频率尖叫：五厘米、十厘米的小虫还没飞到就纷纷坠地抽搐，三十厘米的大个子也只能慢慢挪，整个虫穴的虫都从结晶管道上掉了下来；晶鳞蜥蜴伤不了它们。\n贝希摩斯飞回东方故地时，从空降仓里走出的也是粉碎者，它们在沙下挖了三米多深，挖出了旧航母，再钻回空降仓，靠顶上鼓起的气囊升空回收。在蔓藤蕨的速成丛林里，它们一边用弹出的锥角撞断蕨丛一边前进；尖柱歼灭战中，空降仓的常见配置之一就是一个炮击者加一个粉碎者。\n地下的印加战争里，粉碎者是第二波部队，与黑角甲虫角对角撞在一起，力量和数量不相上下，它便弹出锥角把对方的角硬生生打断；可粘蝎射出的粘球打在它的锥角和节肢上，让它失去了速度和力量，只好退下让炮击者顶上。之后它和绞木者一起冲击裂地者最脆弱的腹部，逼退了刽子手。大坍塌中它们在前面撞开蕨木开路，用声囊发出裂地者回声语里的“死亡”，猛撞一公里宽的岩盾，却被岩盾上冒出的蠕虫浇满易燃液体，陷进一片火海。',ch:'卷三《朝深渊进攻》《结晶之中的战争》《奇布查的尽头》《虫穴之主》《一亿年前的遗失物》《沙漠上的丛林》《尖柱歼灭战》《冲向战场》《围攻裂地》《在崩溃中前进》',rel:['chibcha','kongjiang','zhanxie','crystalcave','jinglin','behemoth','inca','liedizhe','manteng','hangmu','spires']},
 {id:'lvtanshan',n:'绿毯伞 · 播种者',c:'琳的造物',r:'north',e:[2],ll:[32.6,6.2],s:'长着长柄的伞状绿毯，占地小，哪里都能放。',
  d:'琳的基地后来“回归原始”：不再铺开绿毯，而是长出繁殖仓、制造兵种狩猎，其中名为“播种者”的兵种负责寻找合适的地方放置绿毯伞。家园树的外皮上、盐湖的基地里都种满了它们，盐湖的绿毯还兼职过滤盐水，慢慢引来许多生物在那里生活。',ch:'卷三《夏之末》',rel:['lvtan','hometree']},
 {id:'fuchouteng',n:'复仇之藤',c:'物种',r:'west',e:[3,4,5],ll:[5.6,-113.4],s:'白骸龙之岛上，在树被砍光的地方疯长的“报复之藤”。',
  d:'白骸龙离不开木头，砍树砍到停不下来，整座岛几乎被砍光，没有树的地方便长出这种藤：长得极快，没有木材可用，身上的小针扎到会昏迷一两个昼夜。如果把它连根拔起，过一个昼夜，拔它的白骸龙全身都会长出藤苗，最后被藤根贯穿而死；放火烧，它也会在灰烬里重生。\n琳觉得，是原来的大树一直压着这种藤，树没了它才疯长；所谓“复仇”大概是种子藏在根部，拔的时候溅到对方身上寄生。白骸龙一次次把木头“归还”给木之灵：最后一次，两个王领着几万白骸龙高举画着森林的石画，用石头拼成的大弹弓把木材抛进藤林，圆木则推着滚到林边。藤从此不再往城里蔓延，白骸龙只用石头，后来的银甲龙船上也找不到一块木头。',ch:'卷四《木之灵》卷四《归还之日》卷五《银色远征者》',rel:['baihai']},
 // ---------- 卷二 ----------
 {id:'tanwuzhe',n:'探雾者',c:'琳的造物',r:'east',e:[5],ll:[-9,73],s:'一厘米长、蜻蜓般的微型兵种，在浓雾里追踪那座会飞的结晶岛。',
  d:'贝希摩斯与脑袋虫控制的那座岛交战时，爆弹不只造成了伤害，还把大量“卵”黏在了岛的表面；它们孵成一厘米长、像蜻蜓的微型兵种“探雾者”，随岛在浓雾里飞了很久，始终没飞出原来云海的范围。岛面光滑如结晶，布满整齐的六角形痕迹，倒钩勾不住，只能用吸盘爬；贝希摩斯炸出的坑内壁已被修得光滑无缝，到处找不到入口。琳留下一些就地凝固作定位，其余聚到岛底轰鸣的喷气口准备钻进去，喷口却突然合上。雾散开，下方升起一座几乎一样的岛，停在一米外，边缘竖起结晶墙把两岛接合；下方伸出六角结晶柱，一个探雾者刚敲了敲就被光线烧成焦炭，接着光线齐发，夹缝里的探雾者全灭，只剩一只。\n结晶表面随后像在对它说“进来”，一块六角形打开，刚好容它钻进蜂房般的通道。通道里充满脑波信号，墙后有闪烁的怪光，后来又有一厘米大、学着它前进后退的大气史莱姆幼仔；一面面薄薄的结晶墙用白骸龙文字写着“你想要什么？”“停下，交流”“我们知道，你是什么”，又说双方可以没有战争、互相学习。琳问玛雅在哪，墙升起放行，它顺着斜坡下到一个灌满似水怪液的几米见方水箱，被封在里面。教长说“创造者”对抓到的一切都这样，要确保完全控制，一旦失效就慌张，然后杀掉——液温随之升到快要沸腾。它把体表硬化、器官转成原始状态，其实扛得住；琳还发现这种“瓦解者提取液”的隔绝效果遇高温会变弱。琳故意打开外壳让它死去，岛这才动身；它们以为清除了琳，却除不掉看不见的东西——琳早在岛面留下了模拟者，探雾者走过的结晶壁和通道里也抹满了能在虚空中生活的原始细胞。后来琳在脑袋虫的梦里看到，用光线打探雾者、驱使另一座岛夹住它们的，都是脑袋虫自己。',ch:'卷五《追踪》《交流？》《无法排除的间谍》《构造制造装置》',rel:['naodai','behemoth','moni','creator2','jiaozhang','xianshi','daqi','anying']},
 {id:'kaikai',n:'凯凯 · 云魟',c:'物种',r:'east',e:[5],ll:[-14,77],s:'扇动近四十米透明巨翼的云魟，大气生物里唯一的分工型物种。',
  d:'云魟平常在黑暗云海上头飘来飘去，却不是独立的生物，而是庞大群体的一份子；白骸龙把它们统称为“凯凯”，意思是“云鬼”。它从翼下洒下粉末般的小球，落进虫群里噼啪炸开，专炸眼睛和关节；它身上还会飞起大量别的生物一起参战。\n白骸龙的学院早就把“凯凯”当成大威胁，组织毕业生去黑暗云海调查，一艘探索船就在那里坠毁了。云魟身上还会飞出翼展一米的小云魟去撞爆甲；群里也有长满尖刺、像荆棘的成员。但裂地者一夹就能把云魟的头夹烂，飞行虫群赶到后，凯凯节节败退，最后逃离了战场。',ch:'卷五《远处的观望者》卷五《态度的转变》《坠毁的消息》《呼唤》',rel:['zhiyunzhe','cloudsea','inca']},
 // ---------- 卷三 ----------
 {id:'ruibing',n:'锐冰',c:'物种',m:'void',sec:7,e:[7],p:[-180,-90,-320],s:'禁地洞穴里倒挂成群、像石头鸟的生物，见光就成千上万地扑上来。',
  d:'神民之地的禁地里，一支丢下飞行器、在漆黑洞穴里摸索的士兵队伍关掉了所有灯，琳的绒球却在它们身后突然亮起光来。洞里的危险随即扑出：一群样子像鸟、嘴尖、伸着翅膀状结构的东西，每只只有十厘米，看着像石头做的，数量多到灯一亮就布满了视野。琳从飞行器的资料里查到它们叫“锐冰”，对光极端敏感，会疯狂冲向任何发光的地方，生态不明。能量武器的热光一下就能把它们打穿瓦解，它们很不耐高温；可它们也会撞向开火的士兵，虽然穿不透护甲，却一层层把士兵裹住，被裹住的士兵就像冻住一样停火、不出声，一动不动地飘在空中。队长早就先躲进暗处，才喊大家别再射击，射击只会招来更多锐冰。士兵们只能冲进锐冰飞出的那个洞，一进黑暗，锐冰就从身边飞过而毫无察觉。最后剩下五十个士兵，二十多个同伴成了外面飘着的“冰雕”。\n那个洞宽上百米，却只有三米高，洞顶满是钟乳石般的尖柱，锐冰就倒挂在尖端微微摇晃，像在睡觉；绒球伸绒毛戳了一只，它毫无反应，非得够亮的光才会让整群出动。资料还说，只要有一只动了，别的即使没看见光也会跟着动，所以必须确保每一只都在范围之外。再往前，洞顶升到三十多米，地上满是坑洼，锐冰渐渐不见，队长才让大家开灯。\n后来队长独自逃出禁地时说起：它们沾上“耀斑”洒下的甩不掉的荧光后，又遭到另一种锐冰袭击，形态同样像鸟，却只有一厘米大，攻击方式一样，会大量黏在护甲上。琳发现它们好像能干扰护甲里的温度调节装置，让护甲内部瞬间降到极低温——队员就是这样被“冻住”的，具体原理还没细查。',ch:'卷六《冰冷与黑暗》《幽灵与轰炸者》',rel:['v_shenmin','v_kraken','v_edgeeye']},
 {id:'zhicao',n:'智草',c:'物种',m:'void',sec:7,e:[7],p:[120,40,-420],s:'长在创造者残骸上、替真菌“思考”的草。',
  d:'玛雅在月的地下找到的一片白色“草坪”：每棵草都有根，靠地下水和创造者的残骸过活，还能像蠕虫一样爬、缩进地里。单棵草的神经并不完整，连在一起才能思考，整片草坪就是一颗脑。它会自动解析瘟疫真菌发来的信息，教它们怎么拼出复活的灭绝生物——像真菌的脑，却没有自己决定的余地。玛雅推测它是受创造者储存的病毒影响进化来的，把它送进“进化梦境”；一碰到梦境之脑，它头一次开口说话，有了自己的思维，不再替真菌回信。它记得自己是创造者造来辅佐月里那些庞大生物的，却从没见过它们。它还会不由自主地借月的传送器官往虚空某处发信号——琳顺着这些信号，找到了神的平台和旅者。',ch:'卷六《创造的遗留》《信息发送》《疯狂的崇拜者》《目标明确》《是什么东西》',rel:['c_maya']},
 {id:'shengyan',n:'生岩',c:'物种',m:'void',sec:8,e:[8],p:[-200,30,-120],s:'外表像石块的巨大生物，本身就等于一艘战舰。',
  d:'碎石区真正的本土物种，最初尔什民分不清它和普通的石头，直到偶然进入它的内部。它能放出许多“部队”作战，尔什常让生岩加入舰队对抗蒸腾者——但最初与尔什民敌对时，也有生岩偷袭过飞行的队伍。琳认为，在米德加尔特黑暗空间里制造熔毁地带投影的，就是一个生岩。\n它们最早在一块叫“黄昏之石”的巨石附近被发现，像航母一样能放出成群的部队，一开始全力攻击尔什民。后来凝固生物越冒越多，生岩主动用尔什语找上门，提议联手；它们和尔什研究员一起造出了驱赶凝固生物的武器。那块三百多米、带着冻住的微生物、在黑暗空间里投影出熔毁地带陆地的石头，就是一个生岩，它是受托去放投影的，被琳发现后就传送逃走了。',ch:'卷六《战斗资料》《生岩》《凝固的接触》《惩罚》',rel:['v_vine','v_zhengteng','v_rongui','v_huanxing']},
 {id:'luxi',n:'露西',c:'地理',m:'void',sec:9,e:[9],p:[-420,80,200],s:'虚空中的巨大空间站，里面有三座城市。',
  d:'它很像天宫市：高耸的建筑、干净的街道、华丽的设施和极少的广告。空间站不是尔什民建的，而是它们在虚空中发现的，除了尔什民，还有很多虚空生物造访。住在那里的尔什民几乎把体力活都丢给了机械。后来所有基地大规模传送撤离，几百个尔什民却不知为什么出现在虚空里一块几公里的碎石上，不停地试着联络“露西”。\n挖掘队在露西深处挖到了闪光生物的古老建筑，从资料看，那是闪光生物最早出发的第一支探险队留下的。',ch:'卷六《有一个地方》《空间站@1929》卷六《很古老》',rel:['ex_planet','v_headstation','v_shanguang','ex_research']},
 {id:'huannaoyu',n:'换脑鱼',c:'物种',m:'void',sec:10,e:[10],p:[-300,-40,260],s:'下半身是长鱼尾、脑腔里轮流工作着两颗脑的生物，在工作空间为造舰长出力。',
  d:'下半身是一条长长的鱼尾，上半身有双手和头，身体拉直有五米多长，平时立起来和尔什民差不多高，靠尾巴在地上挪动，很像尔什民神话里的生物，却是别处来的细胞生物，琳叫它“换脑鱼”。它的脑腔里有两颗完整的脑轮流工作，有点像尔什上能让半边脑休息的海豚；交班时两颗脑会交换信息，还互相记下对方犯的错，凡是让身体受伤、带来不快的事都算错。一颗错得太多，犯错少的那颗就把它排出体外，被排的那颗从不反抗，过一阵体内又会长出一颗新脑；两颗脑性格不同，总有一颗不合时宜。它们很讲“大义”，被排出的脑义无反顾，留下的那颗会把它当作为身体牺牲的英雄来缅怀。\n在凝固虚空的工作空间里，换脑鱼地位比较高，比被蒙在鼓里的尔什民知道得多：它们学习尔什民和别的生物的历史文化并加以评论，再把装满知识和思维的脑排出来，堆在贝壳沙滩上；地下砂砾里的大量微生物把这些脑包起来缝合，堆成白色、粘着贝壳碎片、一百多米高的肉山，作为“彗星轰击”的弹药，用来射向能造出舰长的光屑彗星。现在它们排脑多是因为受到威胁，不照空间的规矩做就要受罚。\n任务完成后，一艘一公里长、形似墨鱼骨的死亡战舰降落在沙滩上，各种生物挤进它表面残骸的缝隙。一个两米多高、苹果模样、飘在空中的舰长说它们可以得到新的世界；换脑鱼怒气冲天：为了这莫名其妙的任务，它已经赔进去好多好多个脑！它很想杀了舰长，却忍住了，怕这是大错，以后会被另一颗脑排掉。战舰把这里的十座肉山全部传送进一根直径三十多公里、长度超过五百公里的巨柱上的圆孔里。最后，换脑鱼和约一千万个得到过“承诺”的生物一起被固定在彗星轰击塔顶的平台上，穿着动弹不得的重甲，眼睛被强行对准彗星将要出现的天空。',ch:'卷六《彗星轰击》《准备完全》《被照亮的凝固》',rel:['ng_jianzhang','ng_factory','ng_comet','ng_death','ng_overview','ex_planet']},
 {id:'wendingchong',n:'稳定虫',c:'物种',m:'void',sec:10,e:[10],p:[420,60,320],s:'一米长、两端长满触手的凝固混合寄生虫，信仰“稳定”，要让一切不再变化。',
  d:'模型沙海外的虚空里有一座巨大的空间站，琳在那里找到了当年毁掉血肉生物脑部的大量寄生虫，叫它们“稳定虫”。它们是以凝固物质为主、掺着正常物质的混合生物，身体是一米长的圆柱，上下两端长满触手；智力很高，非常健谈，每只都有自己的意见，目标却总是一致。它们能发出类似舰长生物的信号去影响别的生物的精神，会造许多有特殊功能的道具，比如一个模拟的脑，用来持续指挥所有血肉生物；还能检测和干扰空间。\n它们生来就信仰稳定，想让事物在某个范围内一直运转却不发生变化，至于为什么，它们自己也不知道。它们入侵并拆解血肉生物的脑，控制了整个种群：血肉生物照常活动、操作和修理飞行器，却从不升级，也从不扩散。唯一不满的是食物来源总在变，它们想让血肉生物各自吃进去和排出来的东西形成完美循环，正准备开第一千零二次“完全稳定化”会议。有趣的是它们自身并不稳定，会为了更好地维持周围的稳定而不断“进化”，毫不在意自己的变化；它们也承认，稳定的外表下牺牲了许多东西。\n模型沙海到来时，它们截住了空间，想控制它。琳用舰长器官检测抓来的一只，它却刻意回避，有一部分思维检测不到；站里到处是迷宫般的通道，稳定虫不断发信号干扰琳的微型兵种。琳在一座博物馆里找到拦住沙海的东西——一个三十多米、形似三号界的花朵生物，稳定虫随即从各个出入口涌出，用触手尖射出高温射线消灭了几乎所有微型兵种，只有专门针对它们感知造出的“隐眼”被当成稳定的东西忽略过去。琳把沙海的出入口挪进空间站，从裂缝里伸出绒毛把花朵拖走，绒毛顶着射线照样干活。原来花朵生物当年想暗中对付虚空帝国，稳定虫袭击了它控制的所有肉块的脑，却留下部分神经，混合别的材料还原出它本来的样子并控制了它，让它挪动另一个空间，沙海才被粘住。花朵挪开空间后沙海重新出发，稳定虫进不了空间，只能在站里着急地四处奔跑，好像根本不知道沙海已经走了。',ch:'卷六《爱好稳定》《稳定的中心》《多次改造》《继续旅途@2610》',rel:['v_wending','yinyan','v_huaduo','tn_sand','ng_jianzhang','tn_third','tn_empire']},
 {id:'yinyan',n:'隐眼',c:'琳的造物',m:'void',sec:10,e:[10],p:[470,90,300],s:'眼球模样、约一毫米的微型兵种，专门躲过稳定虫的感知。',
  d:'稳定虫空间站里，稳定虫一发现琳的微型兵种，就用触手射出高温光线把它们消灭，整个站里到处是巡逻的稳定虫。隐眼却留在博物馆里继续观察：琳把它做成一颗眼球的样子，差不多一毫米大，比别的微型兵种大得多，但正是针对稳定虫那种会给目标“归类”的、可调整的感知系统特制的，所以一直没被发现。',ch:'卷六《稳定的中心》',rel:['wendingchong']},
 {id:'qiyi',n:'气蚁',c:'物种',m:'void',sec:10,e:[10],p:[-120,90,-380],s:'鼓着气球般的腹部、里面装满绒球空气的生物。',
  d:'它们待在虚空间歇泉“绒球泉眼”附近，琳的骸龙兵种降落时毫无反应。琳检测后发现，鼓起的部分装的全是来自绒球的空气——准确地说，是恐龙大陆丛林里的空气，里面还有那里的微生物、植物种子，甚至侏儒排泄物的碎屑。这说明泉眼曾经连接着恐龙大陆。',ch:'卷六《接通？》《工厂@2493》',rel:['west','zhuru']},
 {id:'henggu',n:'恒古之泥',c:'现象',m:'void',sec:10,e:[10],p:[260,-90,-120],s:'被红浆当作“神器”的、传说中一只比古代泥浆更古老的泥浆的尸体。',
  d:'红浆是一群从古代泥浆的控制下反抗出来、体内脑部汇聚起来的小型古代泥浆。它们从模型沙海里挖出一块不起眼的石头，首领用奇迹生物的语言激动地向同伴解说：这件“神器”不是什么工具，而是传说中一只古代泥浆的尸体，它们刚给它起名叫“恒古之泥”——比常见的古代泥浆古老得多，来历说不定能一路追到奇迹生物的年代，所有古代泥浆都听过它的名声。恒古之泥和如今的古代泥浆并没有根本的差别，只要古代泥浆拿到变形的数据，就能在短时间内整体“升级”成恒古之泥。红浆如今不论吃多少都长不大，连从前还能长成的泥浆领主也长不成了，它们希望把自己那具古代泥浆尸体升级，借恒古之泥体内许多强大的器官解决这个难题，只是对它其实所知不多，只当作一线希望。那具尸体只是神经死了，大部分器官还活着，升级的也只是这些器官，死去的古代泥浆不会醒来；道具泥浆则已拿到古代泥浆脑部的数据，打算许多个拼起来变成它的脑。\n一直在古代泥浆体内调查的无形，也查到了恒古之泥：它的某些器官可以当作容纳无形本体的容器，让它挣脱空间的束缚去到正常虚空；它弄不到数据，便盯上了能把一件东西内外一切完整记录下来的模型沙海。一万个红浆护送神器下到尸体深处的“载入点”，还备好了叶片形的爆弹启动装置，万一升级后控制不住，就把这里全炸掉。其实神器一靠近，尸体就已开始读取数据、全面变化：红浆撤退并发动风暴攻击时，一部分器官已经变完，给了它躲进别的空间（无形的空间）和移动追杀的能力。无形还打算把升级后会大量显现在恒古之泥身上的奇迹转移到尔什的世界去，它和尔什谈的交易其实是骗局。升级进行到一半就停了；后来无形控制这具躯体去对抗死亡战舰，它的表面在光束下迅速瓦解。',ch:'卷六《神器？》《沟通》《变化@2641》《新的剧情》《数据@2647》《载体》《地面的事件》《奇迹的目标》《奇迹集合？》',rel:['v_nijiang','tn_wuxing','tn_sand','v_wuyi','ng_death','ex_planet']},
 {id:'caise',n:'彩色舰长',c:'物种',m:'ningu',r:'ng10',e:[10],p:[380,30,180],s:'在收集彩色光屑的死亡战舰里诞生的新舰长。',
  d:'和原本的舰长不同，它会主动袭击别的生物、吸取对方的思维，并发出“停止……停止……”的催眠信号，一般生物会定在原地无法动弹，琳和诺却还能后退避开。琳曾在那些死亡战舰里观察过它们制造舰长的过程，所以一眼就认出了它。',ch:'卷六《复杂的显现》',rel:['ng_jianzhang','ex_nuo']},
 {id:'tunman',n:'凝固吞鳗',c:'物种',m:'ningu',r:'ng10',e:[10],p:[-520,-30,420],s:'一百多米长、像吞鳗一样张开巨嘴的凝固生物。',
  d:'它在死亡战舰周围的废弃物堆积区游荡，张开大嘴把漂着的“幽灵”全部吞进去，吞饱了全身都闪闪发光；它对死亡战舰却没有意见，见了就绕开。附近的废弃物块上还爬着像海参的生物，用粗短的腕足挖出碎屑堆成小山。前方漂着直径一百公里的古战舰。',ch:'卷六《古代之物》',rel:['ng_galaxy']},
 {id:'yongheng',n:'永恒观察者',c:'现象',m:'ningu',r:'ng10',e:[10,12],p:[80,140,-520],s:'米德加尔特身体粉碎后的最后形态：意识扩散于虚空，能感知一切却无法干涉。',
  d:'米德加尔特从幽灵般的幼仔起步，与蒸腾者塑造的管道融合而成熟，此后几乎没有寿命的尽头，对多数文明来说如同神明。但身体若被完全粉碎，它的意识就会在凝固虚空里扩散开去，进入琳所称的“永恒观察者”状态：从此不会真正死去，能永远感知虚空中的一切，却什么都无法干涉，就像个性生物传说里死后化作星星俯视大地的那样。没有谁说得清这种意识究竟是什么、有多大，它还会不断扩展。许多米德加尔特最终会主动舍弃管道躯体，进入这个阶段。\n琳遇到的那个米德加尔特是个异类。它被巴士们粉碎前就设计好了一切——死亡战舰的每次行动、那颗松果和里面负责计划的生物——自己并不参与。它想把飘渺的意识变成真实而持续有影响力的形态：趁意识还没扩散得太大，让死亡战舰在一千个码头周围筑起墙壁，把这些空间整合起来，限住意识的扩展，形成一个全新的“米德加尔特虚空”，打算以此去旅行，到它从前去不了的地方。尔什拦截死亡战舰，一度打乱了这个计划。松果里的创造者认为，永恒观察者的意识再怎么扩散也有极限，所以它才要造一个更大的躯体。尔什自己也想变成这种状态，在一个像电影般的小空间——米德加尔特与意识起反应的“意识转化点”——里转化了意识，最后却把自己变成了巴士生物最原始的思维结构“细碎空间”。\n后来琳在崩裂虚空又碰上一个很久以前死在那里的古老米德加尔特。崩裂虚空的研究者发现，米德加尔特死后，它的文明、能力乃至爱好都会以某种形式显现在周围环境里，环境中还会诞生新的生物来组装新的米德加尔特。这个个体的永恒观察者状态与众不同：它同时“看”着不同的时代，显现为“幻象世界”，各个时代的景象、生物与文明混在一起，可以说是它的记忆，也是这种状态的可视化；别的生物提升认知就能与它的状态连接、看见幻象，幻象生物则是它没算到的副产品。它远没有米德加尔特虚空那么大，漫长岁月里也从未成长。莎琳认为恒星里那台像望远镜的拍星器，真正的用处可能是转移它的意识；它向能解析拍星器的生物开放了控制幻象世界的权限。散落在虚空各处的幻象被逐个激活，它的意识就会觉醒，借此从无法影响任何事物的状态变成有“实体”的状态；它造出和莎琳一样大的黑影与莎琳争夺控制，把莎琳当作计划的备用部分，最后让恒星“消失”，把莎琳的意识连进它的空间。可就在这时，它的意识却忽然从那里消失了——这本不该发生，否则也称不上永恒。',ch:'卷六《永恒的观察》《完成了……但还得继续》《发现@2366》《原始化》卷七《熟悉之物》《命运@231》《连接的时代》《形成》《真实的幻象》《入侵@249》《接触@253》《飞向》《消失@259》',rel:['mg_overview','v_huanxiang','v_paixing','v_benglie','ng_pinecone','ng_death','ng_mixu','c_sarin']},
 {id:'hongtianxie',n:'轰天蟹',c:'物种',m:'erxi',r:'ex_eu',e:[9],ll:[45,8],s:'塔形身体、能突然爆响着飞上高空的蟹。',
  d:'名字是比露起的。它直径一般一米，最显眼的本事是突然发出爆响、像飞弹一样冲上天。它们袭击过天宫学院的广场，倒地的学生之间到处游荡着轰天蟹。\n它们是吃腐肉的，本来飞不到学院那么高——是一块三十多米、长满藤壶和蟹虾的“飞跃礁石”把它们运了上去。礁石上一根根带眼球的触手其实是独立的生物，能感知空间的异常；同一时刻学院和传送器官的联系出了问题，整座学院落进了云海。',ch:'卷六《具体目标》卷六《袭击的持续@1818》《在礁石》',rel:['c_bilu','c_veronica']},
 {id:'tuya',n:'秃鸦',c:'物种',m:'erxi',r:'ex_eu',e:[9],ll:[40,25],s:'没有羽毛、翼展两米的“乌鸦”。',
  d:'光秃秃的身体加上展开的秃翅，以尔什民的审美看相当怪异。它在一片树根会挪动的巨叶沼泽里扑向间谍和比露，被打死以后，两个干脆把它的尸体当筏子，在沼泽上缓缓漂荡。比露觉得这个没毛的东西实在太恶心了。\n琳看出它就是普通乌鸦变来的：老往沼泽深处钻着找虫吃，羽毛慢慢退光，在这个进化加速的空间里还长成了能当船的大个子。尸体能在沼泽上漂着走，是因为底下有一群搬运尸体的小生物在推。',ch:'卷六《另一边@1824》《这个生物》',rel:['c_bilu','c_veronica']}
,
 // ---------- 地下世界（沙漠之下） ----------
 {id:'ud_sky',n:'洞顶星河',c:'地理',m:'under',r:'ud',e:[2],z:300,ang:180,h:30,k:'none',s:'洞顶布满绿色的发光粉末，抬头看去像一整片银河。',
  d:'地下世界没有太阳，照亮这里的是洞顶无数绿色光点。飞行者往上看，它们密的地方层层叠叠，稀的地方只有几点，一闪一跳，像夜空下的银河——可这里是洞穴，哪来的星星？光确实是真的，有些小生物被吸引着朝洞顶飞去。',ch:'卷三《地底世界》',rel:['under','ud_fern']},
 {id:'ud_fern',n:'蕨木丛林',c:'地理',m:'under',r:'ud',e:[2],z:1100,ang:0,h:24,k:'none',s:'地下的森林：高大的蕨木在微光里生长。',
  d:'地下世界照不到太阳。利维坦的飞行者往上看，满眼都是绿色的光点，密处层层叠叠，稀处只有几点，像夜空下的银河——可这里是洞穴，哪来的星星？那确实是光：三百多米高的洞顶上挂满锥形的发光钟乳，一闪一闪，结晶的发光粉尘、橙色的真菌和微小的生物都在发光，还有小生物被吸引着往上飞。在这片微光之下，洞穴底部长着一片高大的蕨木丛林，从树冠上方望去一直铺到天边。\n蕨木有二十多米高，树干笔直，不像扭曲树那样盘绕，顶上展开蕨叶似的叶子，长得又密又茂盛，完全靠洞顶的光过活。它们很脆，一支冲锋的军队就能轻易撞倒整棵树，不像长成的扭曲树那么结实。家园树附近最密，每隔两百米左右就有一棵家园树立在蕨木之间；往山峰那边的岩石荒原，植物就稀了，家园树要一两公里才有一棵。林子里住着蜥蜴、蟑螂和许多节肢动物，这也是印加虫群的地盘：它们用一道死亡尖刺的墙把自己的蕨木林围起来，和光秃秃的岩石荒原隔开。印加战争中，领头的裂地者把整片蕨木连根撕起；北方时代末的大洪水里，海水冲过森林，折断了数不清的蕨木，这片丛林就此毁掉。骷髅岛以西那座无名大岛上有它的近亲，同样二十多米高的巨型蕨树，树皮却很硬，不像蕨木那么脆。',ch:'卷三《地底世界》《生物之脑》《印加生态》《地下世界的边境》《军备》《战争》《被淹没的世界》《只有骨架的岛屿》',rel:['under','ud_sky','ud_rock','hometree','inca','siwangjianci','liedizhe','ev_war']},
 {id:'ud_fossil',n:'复活的化石',c:'事件',m:'under',r:'ud',e:[2],z:1800,ang:-25,h:16,k:'none',s:'印加虫群在地下复活化石，夺取其他物种的能力。',
  d:'地下的一棵家园树专门用来复活化石。黑蜂在树旁挖出鱼骨、甲壳之类的古老骨架，挖完就把洞填回去；碎骨被粘回完整的样子，按大小排得整整齐齐，每种只放一副。一种小飞虫吸食化石里的东西，再被肥虫吃下，大约十个昼夜后，肥虫体内就会长出一条化石里的古代鱼——可几乎全是畸形的，多出几只胸鳍，甚至长了两个脑，琳从没见它们完全成功过。琳后来猜，生物死得越久越难复活，刚灭绝不久的裂地者才被印加完整地“偷”了过去。',ch:'卷三《化石》《实验室与山峰通道》《印加生态》《偷猎者》',rel:['inca','under','heifeng','liedizhe']},
 {id:'ud_rock',n:'干裂岩地',c:'地理',m:'under',r:'ud',e:[2],z:2300,ang:20,h:14,k:'none',s:'蕨木丛林之外，是大片干裂的岩地。',
  d:'丛林的边缘之外，地面变成一片片干裂的岩石，裂缝纵横。通往这里的洞穴十分曲折：从湖底进来时往下，到堵石处往上，之后又往下，还左拐右拐，琳觉得简直像‘过山车’，虽然它也不知道过山车是什么；越往深处，原本静止的水开始流动，而且越来越快。',ch:'卷三《地下世界的边境》',rel:['under','ud_spikes']},
 {id:'ud_spikes',n:'死亡尖刺之墙',c:'印加',m:'under',r:'ud',e:[2],z:2900,ang:0,h:60,k:'none',s:'印加种下的一整面尖刺之墙，横断地下世界。',
  d:'印加在地下种下的“死亡尖刺之墙”：密密麻麻的尖刺从地面一直长上去，像一道拦住去路的墙。',ch:'卷三《地下世界的边境》',rel:['inca','under']},
 {id:'ud_tree',n:'地下家园树',c:'地理',m:'under',r:'ud',e:[2],z:3700,ang:0,h:120,k:'none',s:'三百多米高的家园树，像柱子一样撑住洞顶。',
  d:'地下世界里高达三百多米的家园树，从地面一直长到洞顶，像柱子一样撑着整个空间，印加虫群也住在里面。真菌悄悄侵入了这些树：一棵被蛀空的先倒下，压死了两头炼狱蠕虫；谈判时又一棵从腰间裂开倒下，伸进岩层的枝条把洞顶扯出一个大窟窿，旁边那棵也跟着歪倒。撞地的那一刻整个世界都在颤抖；失去支撑的洞顶裂开几米到十几米宽的缝，巨石和发光生物纷纷坠落。地震本来很好预测，生物们通常早一个昼夜就跑光了，这次却来得太突然：猎手和猎物挤在一起毫不推搡地逃命，许多还没跑几步就被砸成肉泥。随后海水冲入，地下世界变成了峡谷之海。',ch:'卷三《终结战争的第三者》《谈判》《大坍塌》《被淹没的世界》',rel:['hometree','canyon','under']}
);
